fn area(p: &[(i64,i64)]) -> f64 {
    let n = p.len();
    if n < 3 { return 0.0; }
    let mut a = 0.0f64;
    for i in 0..n {
        let (x1,y1) = p[(i+n-1)%n];
        let (x2,y2) = p[i];
        a += ((y1+y2) as f64) * ((x1-x2) as f64);
    }
    a * 0.5
}
fn unit_normal(p1:(i64,i64), p2:(i64,i64)) -> (f64,f64) {
    if p1==p2 { return (0.0,0.0); }
    let dx = (p2.0-p1.0) as f64; let dy = (p2.1-p1.1) as f64;
    let ih = 1.0/ (dx.hypot(dy));
    (dy*ih, -dx*ih)
}
const DEFAULT_ARC_TOL: f64 = 0.25;

fn offset_poly(path: &[(i64,i64)], delta: f64) -> (Vec<(i64,i64)>, f64) {
    let n = path.len();
    let norms: Vec<(f64,f64)> = (0..n).map(|i| unit_normal(path[i], path[(i+1)%n])).collect();
    let ad = delta.abs();
    let arc_tol = (2.0+ad).log10() * DEFAULT_ARC_TOL;
    let spd360 = (std::f64::consts::PI / (1.0 - arc_tol/ad).acos()).min(ad*std::f64::consts::PI);
    let mut step_sin = (2.0*std::f64::consts::PI/spd360).sin();
    let step_cos = (2.0*std::f64::consts::PI/spd360).cos();
    if delta < 0.0 { step_sin = -step_sin; }
    let spr = spd360/(2.0*std::f64::consts::PI);
    let mut out: Vec<(i64,i64)> = Vec::new();
    for j in 0..n {
        let k = (j+n-1)%n;
        let nj = norms[j]; let nk = norms[k];
        let mut sin_a = nj.1*nk.0 - nk.1*nj.0;
        let cos_a = nj.0*nk.0 + nj.1*nk.1;
        if sin_a > 1.0 { sin_a = 1.0 } else if sin_a < -1.0 { sin_a = -1.0 }
        let angle = sin_a.atan2(cos_a);
        let pt = path[j];
        let mut ov = (nk.0*delta, nk.1*delta);
        out.push(((pt.0 as f64 + ov.0).round() as i64, (pt.1 as f64 + ov.1).round() as i64));
        let steps = (spr * angle.abs()).ceil() as i64;
        for _i in 1..steps {
            ov = (ov.0*step_cos - step_sin*ov.1, ov.0*step_sin + ov.1*step_cos);
            out.push(((pt.0 as f64 + ov.0).round() as i64, (pt.1 as f64 + ov.1).round() as i64));
        }
        out.push(((pt.0 as f64 + nj.0*delta).round() as i64, (pt.1 as f64 + nj.1*delta).round() as i64));
    }
    (out, spd360)
